//! Ports of the cases in base/containers/lru_cache_unittest.cc that do not
//! depend on the MemoryCoordinator, plus randomized differential tests.
//! Typed C++ tests run once per cache type (map and set variants, ordered and
//! hashing indexes). Each one becomes a module generated by a macro.

use std::cell::Cell;
use std::collections::BTreeSet;
use std::hash::{Hash, Hasher};
use std::rc::Rc;

use crate::{HashingLruCache, HashingLruCacheSet, LruCache, LruCacheSet};

thread_local! {
    static LIVE_ITEMS: Cell<i64> = const { Cell::new(0) };
}

fn live_items() -> i64 {
    LIVE_ITEMS.with(Cell::get)
}

/// Mirrors the C++ `CachedItem`: it counts live instances on this thread.
/// Each test runs on its own thread, and the tests compare counts relative to
/// the start, so the counter is not shared between tests.
#[derive(Debug, PartialEq)]
struct CachedItem {
    value: i32,
}

impl CachedItem {
    fn new(value: i32) -> Self {
        LIVE_ITEMS.with(|c| c.set(c.get() + 1));
        Self { value }
    }
}

impl Clone for CachedItem {
    fn clone(&self) -> Self {
        Self::new(self.value)
    }
}

impl Drop for CachedItem {
    fn drop(&mut self) {
        LIVE_ITEMS.with(|c| c.set(c.get() - 1));
    }
}

/// `RefCountedData<std::string>` in the C++ test. Shared, and compared by its
/// string contents.
#[derive(Debug)]
struct Item {
    data: String,
}

/// The C++ test wraps `scoped_refptr<RefCountedData<std::string>>` with
/// `DerefCompare`, `DerefEqual` and `DerefHash`. This newtype provides the same
/// `Ord`, `Eq` and `Hash` by dereferencing to the string.
#[derive(Clone, Debug)]
struct ItemKey(Rc<Item>);

impl PartialEq for ItemKey {
    fn eq(&self, other: &Self) -> bool {
        self.0.data == other.0.data
    }
}

impl Eq for ItemKey {}

impl PartialOrd for ItemKey {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for ItemKey {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.0.data.cmp(&other.0.data)
    }
}

impl Hash for ItemKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.0.data.hash(state);
    }
}

fn item(data: &str) -> ItemKey {
    ItemKey(Rc::new(Item {
        data: data.to_string(),
    }))
}

/// xorshift64, a small deterministic PRNG for the randomized tests.
struct XorShift(u64);

impl XorShift {
    fn next_u64(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }

    fn below(&mut self, n: u64) -> u64 {
        self.next_u64() % n
    }
}

/// Port of each `TYPED_TEST(LRUCacheTest, ...)` for one map type.
macro_rules! map_cache_tests {
    ($module:ident, $cache:ident) => {
        mod $module {
            use super::*;

            type Cache<K, V> = $cache<K, V>;

            // TYPED_TEST(LRUCacheTest, Basic)
            #[test]
            fn basic() {
                let mut cache: Cache<i32, CachedItem> = Cache::new(None);

                // Check failure conditions.
                assert!(cache.get(&0).is_none());
                assert!(cache.peek(&0).is_none());

                const KEY1: i32 = 5;
                let inserted = cache.put(KEY1, CachedItem::new(10)).map(|(k, _)| *k);
                assert_eq!(inserted, Some(KEY1));
                assert_eq!(cache.len(), 1);

                // Check that item1 was properly inserted.
                let found = cache.get(&KEY1).map(|(k, v)| (*k, v.value));
                assert_eq!(found, Some((KEY1, 10)));
                let found = cache.peek(&KEY1).map(|(k, v)| (*k, v.value));
                assert_eq!(found, Some((KEY1, 10)));

                const KEY2: i32 = 7;
                cache.put(KEY2, CachedItem::new(12));
                assert_eq!(cache.len(), 2);

                // item1 is the oldest, since item2 was added afterwards.
                let oldest = cache.iter().rev().next().map(|(k, v)| (*k, v.value));
                assert_eq!(oldest, Some((KEY1, 10)));

                // Retrieving item1 pushed item2 to the oldest position.
                assert!(cache.get(&KEY1).is_some());
                let oldest = cache.iter().rev().next().map(|(k, v)| (*k, v.value));
                assert_eq!(oldest, Some((KEY2, 12)));

                // Remove the oldest item, and item1 is now the only member.
                let removed = cache.pop_lru().map(|(k, v)| (k, v.value));
                assert_eq!(removed, Some((KEY2, 12)));
                assert_eq!(cache.len(), 1);
                let next = cache.iter().rev().next().map(|(k, v)| (*k, v.value));
                assert_eq!(next, Some((KEY1, 10)));

                assert!(cache.remove(&KEY1).is_some());
                assert_eq!(cache.len(), 0);

                // Check that Clear() works properly.
                cache.put(KEY1, CachedItem::new(10));
                cache.put(KEY2, CachedItem::new(12));
                assert_eq!(cache.len(), 2);
                cache.clear();
                assert_eq!(cache.len(), 0);
            }

            // TYPED_TEST(LRUCacheTest, GetVsPeek)
            #[test]
            fn get_vs_peek() {
                let mut cache: Cache<i32, CachedItem> = Cache::new(None);

                cache.put(1, CachedItem::new(10));
                cache.put(2, CachedItem::new(20));

                // This does nothing, since the size is bigger than the number of
                // items.
                cache.shrink_to_size(100);

                // Item 1 starts out as the oldest.
                let oldest = cache.iter().rev().next().map(|(k, v)| (*k, v.value));
                assert_eq!(oldest, Some((1, 10)));

                // Peek does not change the ordering.
                assert!(cache.peek(&1).is_some());
                let oldest = cache.iter().rev().next().map(|(k, v)| (*k, v.value));
                assert_eq!(oldest, Some((1, 10)));
            }

            // TYPED_TEST(LRUCacheTest, KeyReplacement)
            #[test]
            fn key_replacement() {
                let mut cache: Cache<i32, CachedItem> = Cache::new(None);

                cache.put(1, CachedItem::new(10));
                cache.put(2, CachedItem::new(20));
                cache.put(3, CachedItem::new(30));
                cache.put(4, CachedItem::new(40));
                cache.put(3, CachedItem::new(50));

                assert_eq!(cache.len(), 4);

                // Keep only the most recent element.
                cache.shrink_to_size(1);

                let first = cache.iter().next().map(|(k, v)| (*k, v.value));
                assert_eq!(first, Some((3, 50)));
            }

            // TYPED_TEST(LRUCacheTest, Owning)
            #[test]
            fn owning() {
                let mut cache: Cache<i32, Box<CachedItem>> = Cache::new(None);
                let initial_count = live_items();

                // Insert an item, then overwrite it.
                cache.put(1, Box::new(CachedItem::new(20)));
                cache.put(1, Box::new(CachedItem::new(22)));

                // There is one item, and one extra live item.
                assert!(cache.get(&1).is_some());
                assert_eq!(cache.len(), 1);
                assert_eq!(live_items(), initial_count + 1);

                // Remove it.
                assert!(cache.remove(&1).is_some());
                assert_eq!(live_items(), initial_count);

                // A cache that goes out of scope releases its values.
                {
                    let mut cache2: Cache<i32, Box<CachedItem>> = Cache::new(None);
                    cache2.put(1, Box::new(CachedItem::new(20)));
                    cache2.put(2, Box::new(CachedItem::new(20)));
                }
                assert_eq!(live_items(), initial_count);

                // Clear() also frees the values.
                {
                    let mut cache2: Cache<i32, Box<CachedItem>> = Cache::new(None);
                    cache2.put(1, Box::new(CachedItem::new(20)));
                    cache2.put(2, Box::new(CachedItem::new(20)));
                    assert_eq!(live_items(), initial_count + 2);
                    cache2.clear();
                    assert_eq!(live_items(), initial_count);
                }
            }

            // TYPED_TEST(LRUCacheTest, AutoEvict)
            #[test]
            fn auto_evict() {
                const MAX_SIZE: usize = 3;
                let initial_count = live_items();

                {
                    let mut cache: Cache<i32, Box<CachedItem>> = Cache::new(Some(MAX_SIZE));

                    cache.put(1, Box::new(CachedItem::new(20)));
                    cache.put(2, Box::new(CachedItem::new(21)));
                    cache.put(3, Box::new(CachedItem::new(22)));
                    cache.put(4, Box::new(CachedItem::new(23)));

                    // Only MAX_SIZE items remain, although more were inserted.
                    assert_eq!(cache.len(), MAX_SIZE);
                }

                // No values are leaked.
                assert_eq!(live_items(), initial_count);
            }

            // TYPED_TEST(LRUCacheTest, HashingLRUCache)
            #[test]
            fn hashing_lru_cache() {
                // Basic check that the cache works with String keys looked up by &str.
                let mut cache: Cache<String, CachedItem> = Cache::new(None);

                let one = 1;
                cache.put("First".to_string(), CachedItem::new(one));
                let two = 2;
                cache.put("Second".to_string(), CachedItem::new(two));

                assert_eq!(cache.get("First").unwrap().1.value, one);
                assert_eq!(cache.get("Second").unwrap().1.value, two);
                cache.shrink_to_size(1);
                assert_eq!(cache.get("Second").unwrap().1.value, two);
                assert!(cache.get("First").is_none());
            }

            // TYPED_TEST(LRUCacheTest, Swap)
            #[test]
            fn swap() {
                let mut cache1: Cache<i32, CachedItem> = Cache::new(None);

                // Insert two items into cache1.
                let inserted = cache1.put(1, CachedItem::new(2)).map(|(k, _)| *k);
                assert_eq!(inserted, Some(1));
                assert_eq!(cache1.len(), 1);

                cache1.put(3, CachedItem::new(4));
                assert_eq!(cache1.len(), 2);

                // Verify cache1's elements.
                let got: Vec<(i32, i32)> = cache1.iter().map(|(k, v)| (*k, v.value)).collect();
                assert_eq!(got, [(3, 4), (1, 2)]);

                // Create cache2 and insert three items into it.
                let mut cache2: Cache<i32, CachedItem> = Cache::new(None);
                let inserted = cache2.put(5, CachedItem::new(6)).map(|(k, _)| *k);
                assert_eq!(inserted, Some(5));
                assert_eq!(cache2.len(), 1);

                cache2.put(7, CachedItem::new(8));
                assert_eq!(cache2.len(), 2);

                cache2.put(9, CachedItem::new(10));
                assert_eq!(cache2.len(), 3);

                let got: Vec<(i32, i32)> = cache2.iter().map(|(k, v)| (*k, v.value)).collect();
                assert_eq!(got, [(9, 10), (7, 8), (5, 6)]);

                // Swap, so cache2 has cache1's elements and cache1 has cache2's.
                cache2.swap(&mut cache1);

                assert_eq!(cache1.len(), 3);
                assert_eq!(cache2.len(), 2);

                let got: Vec<(i32, i32)> = cache1.iter().map(|(k, v)| (*k, v.value)).collect();
                assert_eq!(got, [(9, 10), (7, 8), (5, 6)]);

                let got: Vec<(i32, i32)> = cache2.iter().map(|(k, v)| (*k, v.value)).collect();
                assert_eq!(got, [(3, 4), (1, 2)]);
            }

            // TYPED_TEST(LRUCacheTest, UpdateMaxSize)
            #[test]
            fn update_max_size() {
                const INITIAL_MAX_SIZE: usize = 3;
                let initial_count = live_items();

                {
                    let mut cache: Cache<i32, Box<CachedItem>> = Cache::new(Some(INITIAL_MAX_SIZE));

                    cache.put(1, Box::new(CachedItem::new(20)));
                    cache.put(2, Box::new(CachedItem::new(21)));
                    cache.put(3, Box::new(CachedItem::new(22)));

                    assert_eq!(cache.len(), 3);
                    assert_eq!(cache.max_size(), INITIAL_MAX_SIZE);

                    // Increase the max size.
                    const LARGER_MAX_SIZE: usize = 5;
                    cache.update_max_size(LARGER_MAX_SIZE);
                    assert_eq!(cache.max_size(), LARGER_MAX_SIZE);
                    assert_eq!(cache.len(), 3);

                    cache.put(4, Box::new(CachedItem::new(23)));
                    cache.put(5, Box::new(CachedItem::new(24)));

                    assert_eq!(cache.len(), 5);

                    // Decrease the max size.
                    const SMALLER_MAX_SIZE: usize = 2;
                    cache.update_max_size(SMALLER_MAX_SIZE);
                    assert_eq!(cache.max_size(), SMALLER_MAX_SIZE);
                    assert_eq!(cache.len(), 2);

                    // The oldest items were evicted.
                    assert!(cache.get(&1).is_none());
                    assert!(cache.get(&2).is_none());
                    assert!(cache.get(&3).is_none());
                    assert!(cache.get(&4).is_some());
                    assert!(cache.get(&5).is_some());

                    // Set to zero.
                    cache.update_max_size(0);
                    assert_eq!(cache.max_size(), 0);
                    assert_eq!(cache.len(), 0);

                    // Everything was evicted.
                    assert!(cache.get(&1).is_none());
                    assert!(cache.get(&2).is_none());
                    assert!(cache.get(&3).is_none());
                    assert!(cache.get(&4).is_none());
                    assert!(cache.get(&5).is_none());

                    // Inserting fails.
                    cache.put(6, Box::new(CachedItem::new(25)));
                    assert!(cache.get(&6).is_none());
                }

                // No values are leaked.
                assert_eq!(live_items(), initial_count);
            }

            // Not in the C++ tests. Checks that a cache with NO_AUTO_EVICT
            // keeps everything, and that `max_size` is not used for eviction.
            #[test]
            fn no_auto_evict_never_evicts() {
                let mut cache: Cache<u32, u32> = Cache::new(None);
                for i in 0..100 {
                    cache.put(i, i * 2);
                }
                assert_eq!(cache.len(), 100);
                assert!(cache.get(&0).is_some());
                assert_eq!(cache.len(), 100);
            }

            // Not in the C++ tests. Mutable access changes the value and, for
            // get_mut, the recency. peek_mut does not change the recency.
            #[test]
            fn get_mut_and_peek_mut() {
                let mut cache: Cache<i32, i32> = Cache::new(None);
                cache.put(1, 10);
                cache.put(2, 20);

                // peek_mut does not change the order, so 1 is still the oldest.
                if let Some((_, v)) = cache.peek_mut(&1) {
                    *v += 1;
                }
                assert_eq!(cache.iter().rev().next().map(|(k, v)| (*k, *v)), Some((1, 11)));

                // get_mut moves 1 to the front, so 2 is now the oldest.
                if let Some((_, v)) = cache.get_mut(&1) {
                    *v += 1;
                }
                assert_eq!(cache.iter().rev().next().map(|(k, v)| (*k, *v)), Some((2, 20)));
                assert_eq!(cache.peek(&1).map(|(_, v)| *v), Some(12));
            }

            // Not in the C++ tests. Checks the return values of `put` and
            // `remove` in the cases where C++ returns end() or an item.
            #[test]
            fn put_and_remove_return_values() {
                let mut cache: Cache<i32, i32> = Cache::new(Some(2));
                assert_eq!(cache.put(1, 10).map(|(k, v)| (*k, *v)), Some((1, 10)));
                assert_eq!(cache.put(2, 20).map(|(k, v)| (*k, *v)), Some((2, 20)));
                // The third insert evicts 1.
                assert_eq!(cache.put(3, 30).map(|(k, v)| (*k, *v)), Some((3, 30)));
                assert!(cache.peek(&1).is_none());
                assert_eq!(cache.remove(&2), Some((2, 20)));
                assert_eq!(cache.remove(&2), None);
                assert_eq!(cache.pop_lru(), Some((3, 30)));
                assert_eq!(cache.pop_lru(), None);
                assert!(cache.is_empty());
            }

            // Not in the C++ tests. A zero max size keeps nothing, and `put`
            // returns None for each insert, as the C++ returns end().
            #[test]
            fn zero_max_size_rejects_all_inserts() {
                let mut cache: Cache<i32, i32> = Cache::new(Some(0));
                assert!(cache.put(1, 10).is_none());
                assert!(cache.is_empty());
                assert_eq!(cache.max_size(), 0);
            }

            // Not in the C++ tests. `max_size` on NO_AUTO_EVICT is a C++ CHECK.
            #[test]
            #[should_panic(expected = "NO_AUTO_EVICT")]
            fn max_size_panics_without_auto_evict() {
                let cache: Cache<i32, i32> = Cache::new(None);
                let _ = cache.max_size();
            }
        }
    };
}

/// Port of each `TYPED_TEST(LRUCacheSetTest, ...)` for one set type.
macro_rules! set_cache_tests {
    ($module:ident, $cache:ident) => {
        mod $module {
            use super::*;

            type Cache<T> = $cache<T>;

            // TYPED_TEST(LRUCacheSetTest, SetTest)
            #[test]
            fn set_test() {
                let mut cache: Cache<String> = Cache::new(None);

                cache.put("Hello".to_string());
                cache.put("world".to_string());
                cache.put("foo".to_string());
                cache.put("bar".to_string());

                // Insert a duplicate element.
                cache.put("foo".to_string());

                // Iterate from oldest to newest.
                let oldest_first: Vec<&str> = cache.iter().rev().map(String::as_str).collect();
                assert_eq!(oldest_first, ["Hello", "world", "bar", "foo"]);

                // Iterate from newest to oldest.
                let newest_first: Vec<&str> = cache.iter().map(String::as_str).collect();
                assert_eq!(newest_first, ["foo", "bar", "world", "Hello"]);
            }

            // TYPED_TEST(LRUCacheSetTest, ReplacementIdentity)
            //
            // Putting a duplicate replaces the stored element, not just the
            // recency. The returned value is the new one.
            #[test]
            fn replacement_identity() {
                let mut cache: Cache<ItemKey> = Cache::new(None);
                cache.put(item("Hello"));
                cache.put(item("world"));
                cache.put(item("foo"));
                cache.put(item("bar"));

                // Insert a duplicate element.
                {
                    let foo = item("foo");
                    let new_foo_addr = Rc::as_ptr(&foo.0);
                    let old_foo_addr = Rc::as_ptr(&cache.peek(&foo).unwrap().0);
                    let stored = cache.put(foo).unwrap();
                    assert_eq!(Rc::as_ptr(&stored.0), new_foo_addr);
                    assert_ne!(Rc::as_ptr(&stored.0), old_foo_addr);
                }

                // Iterate from oldest to newest.
                let oldest_first: Vec<&str> =
                    cache.iter().rev().map(|k| k.0.data.as_str()).collect();
                assert_eq!(oldest_first, ["Hello", "world", "bar", "foo"]);

                // Iterate from newest to oldest.
                let newest_first: Vec<&str> = cache.iter().map(|k| k.0.data.as_str()).collect();
                assert_eq!(newest_first, ["foo", "bar", "world", "Hello"]);
            }

            // Not in the C++ tests. `remove` and `pop_lru` work for sets, and
            // `index` iterates all values.
            #[test]
            fn remove_pop_and_index() {
                let mut cache: Cache<String> = Cache::new(Some(3));
                cache.put("a".to_string());
                cache.put("b".to_string());
                cache.put("c".to_string());
                assert_eq!(cache.remove("b").as_deref(), Some("b"));
                assert_eq!(cache.pop_lru().as_deref(), Some("a"));
                cache.put("d".to_string());
                let mut indexed: Vec<&str> = cache.index().map(String::as_str).collect();
                indexed.sort_unstable();
                assert_eq!(indexed, ["c", "d"]);
                assert_eq!(cache.peek("c").map(String::as_str), Some("c"));
            }
        }
    };
}

/// Differential test of a map against a `Vec` model. The model keeps entries
/// in recency order (front = most recent). Each operation runs on both, and
/// the full contents are compared after each one.
macro_rules! map_differential_test {
    ($module:ident, $cache:ident) => {
        mod $module {
            use super::*;

            #[derive(Default)]
            struct Model {
                entries: Vec<(u8, u32)>,
                max: Option<usize>,
            }

            impl Model {
                fn shrink(&mut self, new_size: usize) {
                    while self.entries.len() > new_size {
                        self.entries.pop();
                    }
                }

                fn put(&mut self, key: u8, value: u32) -> bool {
                    self.entries.retain(|(k, _)| *k != key);
                    if let Some(max) = self.max {
                        if max == 0 {
                            return false;
                        }
                        self.shrink(max - 1);
                    }
                    self.entries.insert(0, (key, value));
                    true
                }

                fn get(&mut self, key: u8) -> Option<u32> {
                    let pos = self.entries.iter().position(|(k, _)| *k == key)?;
                    let entry = self.entries.remove(pos);
                    let value = entry.1;
                    self.entries.insert(0, entry);
                    Some(value)
                }

                fn peek(&self, key: u8) -> Option<u32> {
                    self.entries.iter().find(|(k, _)| *k == key).map(|(_, v)| *v)
                }

                fn remove(&mut self, key: u8) -> Option<u32> {
                    let pos = self.entries.iter().position(|(k, _)| *k == key)?;
                    Some(self.entries.remove(pos).1)
                }
            }

            fn contents(cache: &$cache<u8, u32>) -> Vec<(u8, u32)> {
                cache.iter().map(|(k, v)| (*k, *v)).collect()
            }

            fn run(seed: u64) {
                let mut rng = XorShift(seed);
                let max = if rng.below(4) == 0 {
                    None
                } else {
                    Some(rng.below(8) as usize)
                };
                let mut cache: $cache<u8, u32> = $cache::new(max);
                let mut model = Model {
                    entries: Vec::new(),
                    max,
                };

                for step in 0..3000 {
                    let key = rng.below(16) as u8;
                    let op = rng.below(100);
                    match op {
                        0..=39 => {
                            let value = rng.below(1000) as u32;
                            let inserted = cache.put(key, value).is_some();
                            assert_eq!(inserted, model.put(key, value), "step {step}");
                        }
                        40..=59 => {
                            let got = cache.get(&key).map(|(_, v)| *v);
                            assert_eq!(got, model.get(key), "step {step}");
                        }
                        60..=69 => {
                            let got = cache.peek(&key).map(|(_, v)| *v);
                            assert_eq!(got, model.peek(key), "step {step}");
                        }
                        70..=74 => {
                            let got = cache.remove(&key).map(|(_, v)| v);
                            assert_eq!(got, model.remove(key), "step {step}");
                        }
                        75..=79 => {
                            let got = cache.pop_lru();
                            assert_eq!(got, model.entries.pop(), "step {step}");
                        }
                        80..=83 => {
                            let size = rng.below(6) as usize;
                            cache.shrink_to_size(size);
                            model.shrink(size);
                        }
                        84..=88 => {
                            let size = rng.below(8) as usize;
                            cache.update_max_size(size);
                            model.max = Some(size);
                            model.shrink(size);
                        }
                        _ => {
                            cache.clear();
                            model.entries.clear();
                        }
                    }

                    assert_eq!(contents(&cache), model.entries, "step {step}");
                    assert_eq!(cache.len(), model.entries.len(), "step {step}");

                    // The index holds exactly the same keys.
                    let indexed: BTreeSet<u8> = cache.index().map(|(k, _)| *k).collect();
                    let expected: BTreeSet<u8> = model.entries.iter().map(|(k, _)| *k).collect();
                    assert_eq!(indexed, expected, "step {step}");
                }
            }

            #[test]
            fn differential_against_vec_model() {
                for seed in 1..=8u64 {
                    run(0x9E37_79B9_7F4A_7C15 ^ seed.wrapping_mul(0xD1B5_4A32_D192_ED03));
                }
            }
        }
    };
}

/// Differential test of a set against a `Vec` model.
macro_rules! set_differential_test {
    ($module:ident, $cache:ident) => {
        mod $module {
            use super::*;

            #[test]
            fn differential_against_vec_model() {
                for seed in 1..=8u64 {
                    let mut rng = XorShift(0xA076_1D64_78BD_642F ^ seed);
                    let max = if rng.below(4) == 0 {
                        None
                    } else {
                        Some(rng.below(6) as usize)
                    };
                    let mut cache: $cache<u8> = $cache::new(max);
                    let mut model: Vec<u8> = Vec::new();
                    let mut model_max = max;

                    for step in 0..2000 {
                        let value = rng.below(12) as u8;
                        match rng.below(10) {
                            0..=4 => {
                                // Put, which replaces an equal value.
                                model.retain(|v| *v != value);
                                let inserted = match model_max {
                                    Some(0) => false,
                                    Some(max) => {
                                        while model.len() > max - 1 {
                                            model.pop();
                                        }
                                        true
                                    }
                                    None => true,
                                };
                                if inserted {
                                    model.insert(0, value);
                                }
                                assert_eq!(
                                    cache.put(value).is_some(),
                                    inserted,
                                    "step {step}"
                                );
                            }
                            5..=7 => {
                                let pos = model.iter().position(|v| *v == value);
                                let expected = pos.map(|p| {
                                    let v = model.remove(p);
                                    model.insert(0, v);
                                    v
                                });
                                assert_eq!(cache.get(&value).copied(), expected, "step {step}");
                            }
                            8 => {
                                assert_eq!(cache.pop_lru(), model.pop(), "step {step}");
                            }
                            _ => {
                                let size = rng.below(5) as usize;
                                cache.update_max_size(size);
                                model_max = Some(size);
                                while model.len() > size {
                                    model.pop();
                                }
                            }
                        }
                        let contents: Vec<u8> = cache.iter().copied().collect();
                        assert_eq!(contents, model, "step {step}");
                    }
                }
            }
        }
    };
}

