// TEST(LRUCacheIndexOrderTest, IndexIteration)
#[test]
fn index_iteration() {
    let mut ordered: LruCache<i32, CachedItem> = LruCache::new(None);
    let mut unordered: HashingLruCache<i32, CachedItem> = HashingLruCache::new(None);

    // Add items in any order.
    for (key, value) in [(1, 10), (3, 30), (2, 20), (4, 40)] {
        ordered.put(key, CachedItem::new(value));
        unordered.put(key, CachedItem::new(value));
    }

    // Ordered is in key order. Unordered holds all the elements.
    let ordered_keys: Vec<i32> = ordered.index().map(|(k, _)| *k).collect();
    assert_eq!(ordered_keys, [1, 2, 3, 4]);

    let mut unordered_keys: Vec<i32> = unordered.index().map(|(k, _)| *k).collect();
    unordered_keys.sort_unstable();
    assert_eq!(unordered_keys, [1, 2, 3, 4]);
}

// TEST(LRUCacheSimpleTest, TransparentLookup)
#[test]
fn transparent_lookup() {
    let mut cache: LruCache<String, i32> = LruCache::new(Some(10));
    cache.put("some string".to_string(), 4);
    assert_eq!(cache.get("some string").map(|(_, v)| *v), Some(4));
    assert_eq!(cache.peek("some string").map(|(_, v)| *v), Some(4));
}

// Not in the C++ tests. The ordered index is in key order even after
// eviction and re-insertion, and `swap` exchanges the max sizes too.
#[test]
fn ordered_index_after_eviction_and_swap() {
    let mut a: LruCache<i32, i32> = LruCache::new(Some(3));
    let mut b: LruCache<i32, i32> = LruCache::new(Some(1));
    for key in [5, 1, 9, 3] {
        a.put(key, key);
    }
    let keys: Vec<i32> = a.index().map(|(k, _)| *k).collect();
    assert_eq!(keys, [1, 3, 9]);

    a.swap(&mut b);
    assert_eq!(a.max_size(), 1);
    assert_eq!(b.max_size(), 3);
    assert_eq!(a.len(), 0);
    assert_eq!(b.len(), 3);
    let keys: BTreeSet<i32> = b.index().map(|(k, _)| *k).collect();
    assert_eq!(keys, BTreeSet::from([1, 3, 9]));
}
